sqlite3 -json "/data/arabic_dict.db" "SELECT e.id AS entry_id, e.headword, e.headword_norm, e.root, e.root_source, e.pos, e.definitions_text, e.translation_en, e.domain, d.name_ar, d.name_en, d.source_type, d.period, d.death_year FROM entries e JOIN dictionaries d ON e.dictionary_id=d.id WHERE e.headword_norm IN ('اضطراب','الاضطراب','فوضي','الفوضي','شغب','الشغب','ارجاف','الارجاف','فتنة','الفتنة','هرج','الهرج') ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST;" 2>/dev/null | python3 -c "
import json,sys
data=json.load(sys.stdin)
print(f'Total entries: {len(data)}')
for r in data:
    print(f\"--- {r['headword']} | dict:{r['name_ar']} | src:{r['source_type']} | root:{r['root']} | pos:{r['pos']}\")
    if r.get('definitions_text'):
        print(f\"  DEF: {r['definitions_text'][:200]}\")
    if r.get('translation_en'):
        print(f\"  EN: {r['translation_en']}\")
    if r.get('domain'):
        print(f\"  DOM: {r['domain']}\")
